  var W = 1180, H = 740;
  draw.viewbox(0, 0, W, H);

  var NODE_R = 20;
  var HL = '#e8a33d';      // black-height path highlight
  var RING = '#1565c0';    // red-rule ring
  var TN = { x: 660, y: 600 };

  // key : [color, x, y, left, right]
  var T = {
    26: ['B', 660, 110, 17, 41],
    17: ['R', 375, 175, 14, 21],
    41: ['B', 965, 175, 30, 47],
    14: ['B', 230, 240, 10, 16],
    21: ['B', 525, 240, 19, 23],
    30: ['R', 830, 240, 28, 38],
    47: ['B', 1110, 240, null, null],
    10: ['R', 130, 305, 7, 12],
    16: ['B', 340, 305, 15, null],
    19: ['B', 435, 305, null, 20],
    23: ['B', 645, 305, null, null],
    28: ['B', 730, 305, null, null],
    38: ['B', 925, 305, 35, 39],
    7: ['B', 75, 370, 3, null],
    12: ['B', 185, 370, null, null],
    15: ['R', 290, 370, null, null],
    20: ['R', 500, 370, null, null],
    35: ['R', 875, 370, null, null],
    39: ['R', 985, 370, null, null],
    3: ['R', 48, 435, null, null]
  };
  var KEYS = Object.keys(T).map(Number);

  function isRed(k) { return T[k][0] === 'R'; }
  function slotPos(k, side) { var n = T[k]; return { x: n[1] + (side === 'L' ? -24 : 24), y: n[2] + 52 }; }
  function circlePoint(k, side) {
    var n = T[k], dx = (side === 'L' ? -24 : 24), dy = 52, L = Math.sqrt(dx * dx + dy * dy);
    return { x: n[1] + dx / L * NODE_R, y: n[2] + dy / L * NODE_R };
  }
  function curvePath(k, side) {
    var p = circlePoint(k, side);
    return 'M' + p.x + ',' + p.y + ' Q' + p.x + ',' + TN.y + ' ' + TN.x + ',' + TN.y;
  }
  function emptySlots() {
    var out = [];
    KEYS.forEach(function (k) {
      if (T[k][3] === null) out.push([k, 'L']);
      if (T[k][4] === null) out.push([k, 'R']);
    });
    return out;
  }
  function blackHeight(k) {
    if (k === null) return 0;
    var n = T[k];
    var c = n[3];
    var below = (c === null) ? 1 : blackHeight(c) + (T[c][0] === 'B' ? 1 : 0);
    return below;
  }

  function label(g, x, y, str, opts) {
    var t = g.text(str);
    t.font(Object.assign({ family: 'sans-serif', size: 14, anchor: 'middle' }, opts || {}));
    t.cx(x).cy(y);
    return t;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return t;
  }

  /* ── layers ─────────────────────────────────────────────── */
  var bg = draw.rect(W, H).fill('#ffffff');
  var gEdges = draw.group();
  var gCurves = draw.group();
  var gOvLines = draw.group();
  var gNil = draw.group();
  var gNodes = draw.group();
  var gSentinel = draw.group();
  var gBh = draw.group();
  var gOvTop = draw.group();
  var gHover = draw.group();
  var gStatic = draw.group();

  /* ── straight edges ─────────────────────────────────────── */
  KEYS.forEach(function (k) {
    var n = T[k];
    [n[3], n[4]].forEach(function (c) {
      if (c === null) return;
      var m = T[c];
      gEdges.line(n[1], n[2], m[1], m[2]).stroke({ color: '#000', width: 1 });
