  });

  /* ── NIL leaf boxes (convention a) ──────────────────────── */
  emptySlots().forEach(function (s) {
    var n = T[s[0]], sp = slotPos(s[0], s[1]);
    gNil.line(n[1], n[2], sp.x, sp.y).stroke({ color: '#000', width: 1 });
    gNil.rect(30, 17).radius(5).center(sp.x, sp.y).fill('#000');
    label(gNil, sp.x, sp.y, 'NIL', { size: 9.5, weight: 'bold' }).fill('#fff');
  });

  /* ── sentinel curves + root parent arc (convention b) ───── */
  emptySlots().forEach(function (s) {
    gCurves.path(curvePath(s[0], s[1])).fill('none').stroke({ color: '#000', width: 0.75 });
  });
  gCurves.path('M660,90 C596,24 1142,2 1166,300 C1188,476 772,588 688,590')
    .fill('none').stroke({ color: '#000', width: 0.9 });

  gSentinel.circle(52).center(TN.x, TN.y).fill('#000');
  var tnilLab = gSentinel.text('T.nil');
  tnilLab.font({ family: 'Times New Roman, Georgia, serif', size: 19, style: 'italic', anchor: 'middle' });
  tnilLab.cx(TN.x).cy(TN.y + 44);
  gSentinel.node.setAttribute('pointer-events', 'none');

  /* ── nodes ──────────────────────────────────────────────── */
  KEYS.forEach(function (k) {
    var n = T[k];
    var g = gNodes.group().css('cursor', 'pointer');
    if (n[0] === 'B') {
      g.circle(NODE_R * 2).center(n[1], n[2]).fill('#000');
      label(g, n[1], n[2], String(k), { size: 15, weight: 'bold' }).fill('#fff');
    } else {
      g.circle(NODE_R * 2).center(n[1], n[2]).fill('#d4d4d4').stroke({ color: '#333', width: 1 });
      label(g, n[1], n[2], String(k), { size: 15 }).fill('#000');
