      showTooltip(tipFor(k), e);
      if (hovered !== k) { hovered = k; gHover.clear(); if (isRed(k)) showRedRule(k); }
    });
    g.on('mouseleave', function () { hideTooltip(); hovered = null; gHover.clear(); });
    g.on('click', function (e) { e.stopPropagation(); probe(k); });
  });

  /* ── black-height numerals (convention a) ───────────────── */
  KEYS.forEach(function (k) {
    var n = T[k];
    halo(label(gBh, n[1] - 26, n[2] - 17, String(blackHeight(k)), { size: 11.5 }).fill('#101040'));
  });

  /* ── legend + caption ───────────────────────────────────── */
  (function () {
    var x = 34, y0 = 648, dy = 25;
    gStatic.circle(20).center(x, y0).fill('#000');
    halo(gStatic.text('black node').font({ family: 'sans-serif', size: 12 }).move(x + 16, y0 - 8)).fill('#222');
    gStatic.circle(20).center(x, y0 + dy).fill('#d4d4d4').stroke({ color: '#333', width: 1 });
    halo(gStatic.text('red node (drawn gray)').font({ family: 'sans-serif', size: 12 }).move(x + 16, y0 + dy - 8)).fill('#222');
