  })();
  var caption = gStatic.text('(a)');
  caption.font({ family: 'Times New Roman, Georgia, serif', size: 19, anchor: 'middle' });
  var capY = { a: 560, b: 692, c: 520 };

  /* ── probe / hover state ────────────────────────────────── */
  var conv = 'a';
  var hovered = null;

  function clearProbe() { gOvLines.clear(); gOvTop.clear(); }
  function clearHover() { gHover.clear(); hovered = null; }

  function badge(g, x, y, txt, col) {
    g.circle(20).center(x, y).fill(col || '#1f6fb4').stroke({ color: '#fff', width: 1.5 });
    label(g, x, y, String(txt), { size: 10.5, weight: 'bold' }).fill('#fff');
  }

  function drawSlotHighlight(k, side) {
    var n = T[k], sp = slotPos(k, side);
    if (conv === 'a') {
      gOvLines.line(n[1], n[2], sp.x, sp.y).stroke({ color: HL, width: 4, linecap: 'round' });
    } else if (conv === 'b') {
