    } else {
      var p = circlePoint(k, side);
      gOvLines.line(p.x, p.y, n[1] + (sp.x - n[1]) * 0.85, n[2] + (sp.y - n[2]) * 0.85)
        .stroke({ color: HL, width: 4, linecap: 'round' });
    }
  }

