    clearProbe(); clearHover();
    var results = [];
    (function walk(cur, count, trail) {
      var n = T[cur];
      [[3, 'L'], [4, 'R']].forEach(function (s) {
        var child = n[s[0]];
        if (child !== null) {
          walk(child, count + (T[child][0] === 'B' ? 1 : 0), trail.concat([['e', cur, child]]));
        } else {
          results.push({ trail: trail.concat([['s', cur, s[1]]]), count: count + 1, node: cur, side: s[1] });
        }
      });
    })(key, 0, []);

    var drawn = {};
    results.forEach(function (r) {
      r.trail.forEach(function (t) {
        var id = t.join('|');
        if (drawn[id]) return;
        drawn[id] = 1;
        if (t[0] === 'e') {
          var a = T[t[1]], b = T[t[2]];
          gOvLines.line(a[1], a[2], b[1], b[2]).stroke({ color: HL, width: 4, linecap: 'round' });
        } else {
          drawSlotHighlight(t[1], t[2]);
        }
      });
    });
    results.forEach(function (r) {
      var sp = slotPos(r.node, r.side);
      var bx = sp.x + (conv === 'a' ? 15 : 0);
      var by = sp.y + (conv === 'a' ? 14 : 0);
      badge(gOvTop, bx, by, r.count);
    });

    var n = T[key];
    gOvTop.circle(56).center(n[1], n[2]).fill('none').stroke({ color: HL, width: 3 });

    var counts = results.map(function (r) { return r.count; });
    var mn = Math.min.apply(null, counts), mx = Math.max.apply(null, counts);
    var body = 'Amber marks every downward path from node ' + key + ' to a leaf; each badge counts the black nodes on that path, including the black leaf sentinel. ';
    body += (mn === mx)
      ? 'All ' + counts.length + ' paths give exactly ' + mn + ', so bh(' + key + ') = ' + mn + ' — the equal-black-height invariant holds, and it is the same number whichever leaf convention is drawn.'
      : 'The counts range from ' + mn + ' to ' + mx + ', which would violate the invariant.';
    showPopup('Black-height probe: node ' + key, body);
  }

  function childDesc(k, side) {
    var c = side === 'L' ? T[k][3] : T[k][4];
    if (c === null) return (conv === 'b' ? 'T.nil' : 'NIL') + ' (black)';
