      if (c !== null) {
        var m = T[c];
        gHover.circle(56).center(m[1], m[2]).fill('none').stroke({ color: RING, width: 3 });
      } else if (conv === 'a') {
        var sp = slotPos(key, side);
        gHover.rect(40, 26).radius(9).center(sp.x, sp.y).fill('none').stroke({ color: RING, width: 2.5 });
      } else if (conv === 'b') {
        gHover.circle(68).center(TN.x, TN.y).fill('none').stroke({ color: RING, width: 2.5 });
