(function () {
  var host = document.getElementById('container');
  try { host.style.setProperty('--figure-canvas-padding', '8px'); } catch (e) { }
  var draw = SVG().addTo(host).size('100%', '100%');
  draw.attr('preserveAspectRatio', 'xMidYMid meet');

  var R = 21;                          // node radius (user units)
  var SERIF = 'Times New Roman, Georgia, serif';
  var HL = '#e8a33d';                  // black-height path highlight
  var RING = '#1565c0';                // red-rule ring
  var TOPY = 110;                      // root y (stretch anchor)
  var SDX = 26, SDY = 54;              // empty-slot offset from its parent
  var NILW = 38, NILH = 23;

  // key : [color, x, baseY, left, right]
  var T = {
    26: ['B', 660, 110, 17, 41],
    17: ['R', 375, 175, 14, 21],
    41: ['B', 965, 175, 30, 47],
    14: ['B', 230, 240, 10, 16],
    21: ['B', 525, 240, 19, 23],
    30: ['R', 830, 240, 28, 38],
    47: ['B', 1110, 240, null, null],
    10: ['R', 130, 305, 7, 12],
    16: ['B', 340, 305, 15, null],
    19: ['B', 435, 305, null, 20],
    23: ['B', 645, 305, null, null],
    28: ['B', 730, 305, null, null],
    38: ['B', 925, 305, 35, 39],
    7: ['B', 75, 370, 3, null],
    12: ['B', 185, 370, null, null],
    15: ['R', 290, 370, null, null],
    20: ['R', 500, 370, null, null],
    35: ['R', 875, 370, null, null],
    39: ['R', 985, 370, null, null],
    3: ['R', 48, 435, null, null]
  };
  var KEYS = Object.keys(T).map(Number);
  var PARENT = {};
  KEYS.forEach(function (k) {
    if (T[k][3] !== null) PARENT[T[k][3]] = k;
    if (T[k][4] !== null) PARENT[T[k][4]] = k;
  });

  // hand-placed black-height numeral offsets (matches the source figure)
  var BH_DEF = [-33, -11];
  var BH_OFF = { 26: [-35, -14], 17: [-34, -15], 41: [37, 5], 47: [-34, -2], 14: [-34, -13], 21: [-34, -13], 30: [-34, -13], 10: [-34, -12] };

  function isRed(k) { return T[k][0] === 'R'; }
  function blackHeight(k) {
    if (k === null) return 0;
    var c = T[k][3];
    return (c === null) ? 1 : blackHeight(c) + (T[c][0] === 'B' ? 1 : 0);
  }
  function emptySlots() {
    var out = [];
    KEYS.forEach(function (k) {
      if (T[k][3] === null) out.push([k, 'L']);
      if (T[k][4] === null) out.push([k, 'R']);
    });
    return out;
  }
  var SLOTS = emptySlots();

  /* ── layout (responsive vertical stretch, x fixed) ─────── */
  function posOf(v) {
    var Q = {};
    KEYS.forEach(function (k) { Q[k] = { x: T[k][1], y: TOPY + (T[k][2] - TOPY) * v }; });
    return Q;
  }
  function slotAt(Q, v, k, side) {
    return { x: Q[k].x + (side === 'L' ? -SDX : SDX), y: Q[k].y + SDY * v };
  }
  function tnAt(Q, v) { return { x: 660, y: Q[3].y + 165 * v }; }
  function arcPath(Q, tn) {
    var rx = Q[26].x, rt = Q[26].y - R, H = tn.y - rt;
    return 'M' + rx + ',' + rt +
      ' C' + (rx - 64) + ',' + (rt - 67) + ' ' + (rx + 482) + ',' + (rt - 87) + ' ' + (rx + 506) + ',' + (rt + 0.41 * H) +
      ' C' + (rx + 528) + ',' + (rt + 0.757 * H) + ' ' + (rx + 112) + ',' + (rt + 0.99 * H) + ' ' + (rx + 28) + ',' + (tn.y - 10);
  }

  function bboxFor(v) {
    var Q = posOf(v);
    var minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
    function inc(x, y, px, py) {
      minX = Math.min(minX, x - px); maxX = Math.max(maxX, x + px);
      minY = Math.min(minY, y - py); maxY = Math.max(maxY, y + py);
    }
    KEYS.forEach(function (k) { inc(Q[k].x, Q[k].y, R, R); });
    if (conv === 'a') {
      KEYS.forEach(function (k) {
        var o = BH_OFF[k] || BH_DEF;
        inc(Q[k].x + o[0], Q[k].y + o[1], 11, 12);
      });
      SLOTS.forEach(function (s) {
        var sp = slotAt(Q, v, s[0], s[1]);
        inc(sp.x, sp.y, NILW / 2 + 2, NILH / 2 + 2);
      });
    }
    if (conv === 'b') {
      var tn = tnAt(Q, v);
      inc(tn.x, tn.y, 30, 30);
      inc(tn.x, tn.y + 46, 36, 16);
      var rt = Q[26].y - R;
      inc(Q[26].x + 530, rt, 8, 0);
      inc(Q[26].x, rt - 90, 0, 6);
    }
    var capY = maxY + 34;
    inc((minX + maxX) / 2, capY, 22, 16);
    return { x0: minX - 12, y0: minY - 12, w: (maxX - minX) + 24, h: (maxY - minY) + 24, capY: capY, cx: (minX + maxX) / 2 };
  }

  function chooseStretch() {
    var cw = Math.max(80, host.clientWidth - 16);
    var ch = Math.max(80, host.clientHeight - 16);
    var A = cw / ch;
    var v = 1;
    for (var i = 0; i < 4; i++) {
      var b = bboxFor(v);
      var target = b.w / A;                 // height that would fill the frame
      v = Math.max(1, Math.min(1.5, v * (target / b.h)));
    }
    return v;
  }

  /* ── small drawing helpers ─────────────────────────────── */
  function label(g, x, y, str, opts) {
    var t = g.text(str);
    t.font(Object.assign({ family: 'sans-serif', size: 14, anchor: 'middle' }, opts || {}));
    t.cx(x).cy(y);
    return t;
  }
  function halo(t, w) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': w || 4, 'stroke-linejoin': 'round' });
    return t;
  }
  function badge(g, x, y, txt, col, size) {
    var d = size || 26;
    g.circle(d).center(x, y).fill(col || '#1f6fb4').stroke({ color: '#fff', width: 2 });
    label(g, x, y, String(txt), { size: d * 0.56, weight: 'bold' }).fill('#fff');
  }

  /* ── state ─────────────────────────────────────────────── */
  var conv = 'a', vNow = 1, P = {}, TN = { x: 660, y: 600 };
  var probeKey = null, hoverKey = null, BB = null;
  var gEdges, gCurves, gNil, gSent, gOv, gNodes, gBh, gOvTop, gHover, gCap;

  function circlePoint(k, side) {
    var dx = (side === 'L' ? -SDX : SDX), dy = SDY * vNow, L = Math.sqrt(dx * dx + dy * dy);
    return { x: P[k].x + dx / L * R, y: P[k].y + dy / L * R };
  }
  function curvePath(k, side) {
    var p = circlePoint(k, side);
    return 'M' + p.x + ',' + p.y + ' Q' + p.x + ',' + TN.y + ' ' + TN.x + ',' + TN.y;
  }

  /* ── build / rebuild the whole drawing ─────────────────── */
  function build() {
    vNow = chooseStretch();
    P = posOf(vNow);
    TN = tnAt(P, vNow);
    BB = bboxFor(vNow);

    draw.clear();
    var bg = draw.rect(BB.w + 600, BB.h + 600).move(BB.x0 - 300, BB.y0 - 300).fill('#ffffff');
    bg.on('click', function () { clearProbe(); hidePopup(); });

    gEdges = draw.group();
    gCurves = draw.group();
    gNil = draw.group();
    gSent = draw.group();
    gOv = draw.group();
    gNodes = draw.group();
    gBh = draw.group();
    gOvTop = draw.group();
    gHover = draw.group();
    gCap = draw.group();

    // straight parent→child edges
    KEYS.forEach(function (k) {
      [T[k][3], T[k][4]].forEach(function (c) {
        if (c === null) return;
        gEdges.line(P[k].x, P[k].y, P[c].x, P[c].y).stroke({ color: '#000', width: 1.3 });
      });
    });

    // (a) explicit NIL leaves
    if (conv === 'a') {
      SLOTS.forEach(function (s) {
        var sp = slotAt(P, vNow, s[0], s[1]);
        gNil.line(P[s[0]].x, P[s[0]].y, sp.x, sp.y).stroke({ color: '#000', width: 1.3 });
        var g = gNil.group().css('cursor', 'pointer');
        g.rect(NILW, NILH).radius(8).center(sp.x, sp.y).fill('#000');
        label(g, sp.x, sp.y + 0.5, 'NIL', { size: 13.5, weight: 'bold' }).fill('#fff');
        g.on('mousemove', function (e) {
          showTooltip('NIL leaf of node ' + s[0] + ' — every leaf is black and ends a downward path', e);
        }).on('mouseleave', hideTooltip);
      });
    }

    // (b) shared sentinel + curved edges + root parent arc
    if (conv === 'b') {
      SLOTS.forEach(function (s) {
        gCurves.path(curvePath(s[0], s[1])).fill('none').stroke({ color: '#000', width: 0.9 });
      });
      gCurves.path(arcPath(P, TN)).fill('none').stroke({ color: '#000', width: 1 });
      var sg = gSent.group().css('cursor', 'pointer');
      sg.circle(56).center(TN.x, TN.y).fill('#000');
      var tl = sg.text('T.nil');
      tl.font({ family: SERIF, size: 24, style: 'italic', anchor: 'middle' });
      tl.cx(TN.x).cy(TN.y + 46);
      sg.on('mousemove', function (e) {
        showTooltip('T.nil — one shared black sentinel standing in for every NIL leaf and for the root\u2019s parent', e);
      }).on('mouseleave', hideTooltip);
    }

    // nodes
    KEYS.forEach(function (k) {
      var g = gNodes.group().css('cursor', 'pointer');
      if (T[k][0] === 'B') {
        g.circle(R * 2).center(P[k].x, P[k].y).fill('#000');
        label(g, P[k].x, P[k].y, String(k), { size: 21, weight: 'bold' }).fill('#fff');
      } else {
        g.circle(R * 2).center(P[k].x, P[k].y).fill('#d4d4d4').stroke({ color: '#333', width: 1.3 });
        label(g, P[k].x, P[k].y, String(k), { size: 21 }).fill('#000');
      }
      g.on('mousemove', function (e) {
        showTooltip(tipFor(k), e);
        if (hoverKey !== k) { hoverKey = k; gHover.clear(); if (isRed(k)) showRedRule(k); }
      });
      g.on('mouseleave', function () { hideTooltip(); hoverKey = null; gHover.clear(); });
      g.on('click', function (e) { e.stopPropagation(); probe(k, false); });
    });

    // (a) black-height numerals
    if (conv === 'a') {
      KEYS.forEach(function (k) {
        var o = BH_OFF[k] || BH_DEF;
        halo(label(gBh, P[k].x + o[0], P[k].y + o[1], String(blackHeight(k)),
          { family: SERIF, size: 19 }).fill('#101010'), 4.5);
      });
    }

    // caption
    var cap = gCap.text('(' + conv + ')');
    cap.font({ family: SERIF, size: 25, anchor: 'middle' });
    cap.cx(BB.cx).cy(BB.capY);

    draw.viewbox(BB.x0, BB.y0, BB.w, BB.h);

