  }

  /* ── probes ────────────────────────────────────────────── */
  function clearProbe() { probeKey = null; if (gOv) gOv.clear(); if (gOvTop) gOvTop.clear(); }
  function clearHover() { hoverKey = null; if (gHover) gHover.clear(); }

  function drawSlotHighlight(k, side) {
    var sp = slotAt(P, vNow, k, side);
    if (conv === 'a') {
      gOv.line(P[k].x, P[k].y, sp.x, sp.y).stroke({ color: HL, width: 4.8, linecap: 'round' });
    } else if (conv === 'b') {
      gOv.path(curvePath(k, side)).fill('none').stroke({ color: HL, width: 3.4, linecap: 'round' });
    } else {
      var p = circlePoint(k, side);
      gOv.line(p.x, p.y, P[k].x + (sp.x - P[k].x) * 0.8, P[k].y + (sp.y - P[k].y) * 0.8)
